-- VPJ-58 #239 ProfileData. Default denied; local fixture grants are separate.
-- System fallbacks retain the original NOT NULL contracts, never user consent.
create schema profile_data_private;
revoke all on schema profile_data_private from public,anon,authenticated,service_role;
alter table public.user_profiles add column profile_revision bigint not null default 0 check(profile_revision between 0 and 9007199254740990),
 add column profile_saved_fields jsonb not null default '["display_name","travel_pace","locale","currency","distance_unit","temperature_unit","default_departure_time"]';
create table profile_data_private.watermarks_v1(
 owner_id uuid primary key references auth.users(id) on delete cascade,
 profile_revision bigint not null check(profile_revision between 0 and 9007199254740990),
 pace_revision bigint not null check(pace_revision between 0 and 9007199254740990),
 profile_floor bigint not null default 0 check(profile_floor between 0 and profile_revision),
 pace_floor bigint not null default 0 check(pace_floor between 0 and pace_revision)
);
insert into profile_data_private.watermarks_v1(owner_id,profile_revision,pace_revision) select owner_id,profile_revision,pace_revision from public.user_profiles;
create table profile_data_private.proofs_v1(
 transaction_id xid8 primary key,owner_id uuid not null,mode text not null check(mode in('web','native','restore','erase','executor')),
 expected_row jsonb,input jsonb
);
create table profile_data_private.operations_v1(
 request_id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id uuid not null,
 mobile_epoch bigint not null check(mobile_epoch between 1 and 9007199254740990),scope text not null check(scope in('profile-sensitive-data/1','profile-delete-progress/1')),
 profile_id uuid,object_ids jsonb not null,source_digest text not null check(source_digest ~ '^[a-f0-9]{64}$'),
 preview_digest text not null check(preview_digest ~ '^[a-f0-9]{64}$'),captured_at bigint not null,expires_at bigint not null check(expires_at=captured_at+30000),
 request_digest text check(request_digest ~ '^[a-f0-9]{64}$'),state text not null check(state in('previewed','erased')),
 preview_erased boolean not null default false,summary jsonb,copies jsonb,conflicts jsonb,decision jsonb,
 check((scope='profile-sensitive-data/1' and profile_id=owner_id and object_ids='[]') or (scope='profile-delete-progress/1' and profile_id is null)),
 check((state='previewed' and request_digest is null and decision is null) or (state='erased' and request_digest is not null and decision is not null and preview_erased)),
 check(not preview_erased or (summary is null and copies is null and conflicts is null))
);
create index profile_operations_owner on profile_data_private.operations_v1(owner_id,request_id);
do $$declare t text;begin foreach t in array array['watermarks_v1','proofs_v1','operations_v1'] loop
 execute format('alter table profile_data_private.%I enable row level security',t);
 execute format('revoke all on profile_data_private.%I from public,anon,authenticated,service_role',t);
end loop;end$$;
create function profile_data_private.digest_v1(v text) returns text language sql immutable set search_path='' as $$select encode(sha256(convert_to(v,'UTF8')),'hex')$$;
create function profile_data_private.now_v1() returns bigint language sql volatile set search_path='' as $$select floor(extract(epoch from clock_timestamp())*1000)::bigint$$;
create function profile_data_private.deadline_v1(c bigint,e bigint) returns bigint language plpgsql volatile set search_path='' as $$declare n bigint:=profile_data_private.now_v1();begin if n<c or n>=e then raise exception 'PROFILE_EXPIRED';end if;return n;end$$;
create function profile_data_private.empty_copies_v1() returns jsonb language sql immutable set search_path='' as $$select '{"briefPreviews":[],"sharedBriefs":[],"scopedEditContexts":[],"scopedEditWork":[],"recoveryContexts":[],"coreExports":[]}'::jsonb$$;
create function profile_data_private.boundaries_v1(s text) returns jsonb language sql immutable set search_path='' as $$select '{"profile-sensitive-data/1":{"eraseFields":["display_name","travel_pace","locale","currency","distance_unit","temperature_unit","default_departure_time","pace_notice","pace_operation","pace_request","pace_undo"],"retained":["account_auth_sessions","profile_owner_identity_created_at_monotonic_revisions","system_fallbacks_without_pace_consent","explicit_memory_trip_history_financial_provider_and_other_modules","mixed_domain_copies_under_original_controls","immutable_minimal_decisions_operation_replay_fences"],"missing":["external_provider_downloaded_export_backup_and_old_device_copies_not_recalled","mixed_domain_copies_not_cascade_erased","target_backup_and_old_device_acceptance_unverified"]},"profile-delete-progress/1":{"eraseFields":["selected_transient_preview_counts_conflicts_copy_references"],"retained":["actor_selection_hash_time_operation_fences","immutable_minimal_decisions","profile_owner_identity_monotonic_revision_erasure_floor"],"missing":["profile_source_not_modified","unselected_progress","external_copies","target_backup_and_old_device_acceptance_unverified"]}}'::jsonb->s$$;
-- Ephemeral exact-row proof: no caller GUC, role or arbitrary source bypass.
create function profile_data_private.lock_owner_v1(u uuid) returns profile_data_private.watermarks_v1 language plpgsql security definer set search_path='' as $$declare w profile_data_private.watermarks_v1;begin
 perform 1 from auth.users where id=u for key share nowait;if not found then raise exception 'FORBIDDEN';end if;
 if not pg_try_advisory_xact_lock(hashtextextended(u::text,34)) then raise lock_not_available using message='PROFILE_CONFLICT';end if;
 insert into profile_data_private.watermarks_v1(owner_id,profile_revision,pace_revision) values(u,0,0) on conflict do nothing;
 select * into w from profile_data_private.watermarks_v1 where owner_id=u for update nowait;
 perform 1 from public.user_profiles where owner_id=u for update nowait;
 return w;
end$$;
create function profile_data_private.guard_profile_v1() returns trigger language plpgsql security definer set search_path='' as $$
declare proof profile_data_private.proofs_v1;w profile_data_private.watermarks_v1;u uuid;expected jsonb;
begin
 u:=case when TG_OP='DELETE' then OLD.owner_id else NEW.owner_id end;
 select * into w from profile_data_private.watermarks_v1 where owner_id=u for update nowait;
 if TG_OP='DELETE' then
  -- Qualified account deletion keeps its original cascade. Service row deletion
  -- retains the independent watermark, so it cannot reset the source revisions.
  return OLD;
 end if;
 if TG_OP='UPDATE' and NEW.owner_id is distinct from OLD.owner_id then raise exception 'PROFILE_WRITE_FENCE';end if;
 select * into proof from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id() and owner_id=u;
 if not found or w.owner_id is null then raise exception 'PROFILE_WRITE_FENCE';end if;
 if TG_OP='UPDATE' then
  if OLD.profile_revision<>w.profile_revision or OLD.pace_revision<>w.pace_revision then raise exception 'PROFILE_WRITE_FENCE';end if;
  NEW.profile_revision:=OLD.profile_revision+1;
 else NEW.profile_revision:=w.profile_revision;NEW.pace_revision:=w.pace_revision;end if;
 if proof.mode='native' then
  if TG_OP='INSERT' then
   -- The old Native INSERT .. ON CONFLICT is harmless only at the retained baseline.
   NEW.profile_saved_fields:='[]'::jsonb;
   NEW.pace_state:=case when w.pace_floor>0 then 'revoked' else 'unset' end;
   if NEW.display_name is not null or NEW.travel_pace<>'balanced' or NEW.locale<>'zh' or NEW.currency<>'CNY' or NEW.distance_unit<>'kilometre' or NEW.temperature_unit<>'celsius' or NEW.default_departure_time<>'09:00:00'::time
    or NEW.pace_notice is not null or NEW.pace_request is not null or NEW.pace_operation is not null or NEW.pace_undo is not null then raise exception 'PROFILE_WRITE_FENCE';end if;
  else
   if to_jsonb(NEW)-array['profile_revision','profile_saved_fields','updated_at'] is distinct from proof.expected_row-array['profile_revision','profile_saved_fields','updated_at'] then raise exception 'PROFILE_WRITE_FENCE';end if;
   NEW.profile_saved_fields:=OLD.profile_saved_fields;
   if proof.input->>'action'='save' and not(NEW.profile_saved_fields ? 'travel_pace') then
    NEW.profile_saved_fields:=(select jsonb_agg(value order by ord) from jsonb_array_elements('["display_name","travel_pace","locale","currency","distance_unit","temperature_unit","default_departure_time"]') with ordinality f(value,ord) where OLD.profile_saved_fields ? (value#>>'{}') or value='"travel_pace"');
   end if;
  end if;
 elsif proof.mode in('web','erase','restore') then
  if to_jsonb(NEW)-array['profile_revision','updated_at','created_at'] is distinct from proof.expected_row-array['profile_revision','updated_at','created_at'] then raise exception 'PROFILE_WRITE_FENCE';end if;
  if TG_OP='UPDATE' and NEW.created_at is distinct from OLD.created_at then raise exception 'PROFILE_WRITE_FENCE';end if;
 else raise exception 'PROFILE_WRITE_FENCE';end if;
 if NEW.profile_revision<w.profile_revision or NEW.pace_revision<w.pace_revision or NEW.profile_revision<w.profile_floor or NEW.pace_revision<w.pace_floor then raise exception 'PROFILE_WRITE_FENCE';end if;
 return NEW;
end$$;
create trigger profile_data_guard before insert or update or delete on public.user_profiles for each row execute function profile_data_private.guard_profile_v1();
create function profile_data_private.record_watermark_v1() returns trigger language plpgsql security definer set search_path='' as $$begin
 update profile_data_private.watermarks_v1 set profile_revision=NEW.profile_revision,pace_revision=NEW.pace_revision,
 profile_floor=case when exists(select 1 from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id() and owner_id=NEW.owner_id and mode='erase') then NEW.profile_revision else profile_floor end,
 pace_floor=case when exists(select 1 from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id() and owner_id=NEW.owner_id and mode='erase') then NEW.pace_revision else pace_floor end where owner_id=NEW.owner_id;
 return NEW;
end$$;
create trigger profile_data_record after insert or update on public.user_profiles for each row execute function profile_data_private.record_watermark_v1();
create function profile_data_private.guard_watermark_v1() returns trigger language plpgsql security definer set search_path='' as $$begin
 if TG_OP='DELETE' then if exists(select 1 from auth.users where id=OLD.owner_id) then raise exception 'PROFILE_WRITE_FENCE';end if;return OLD;end if;
 if NEW.owner_id<>OLD.owner_id or NEW.profile_revision<OLD.profile_revision or NEW.pace_revision<OLD.pace_revision or NEW.profile_floor<OLD.profile_floor or NEW.pace_floor<OLD.pace_floor then raise exception 'PROFILE_WRITE_FENCE';end if;return NEW;
end$$;
create trigger profile_watermark_guard before update or delete on profile_data_private.watermarks_v1 for each row execute function profile_data_private.guard_watermark_v1();

-- Move the real Native implementation intact, preserving validators, replay and
-- error behavior. Its public wrapper adds the permanent floor before replay.
alter function public.native_travel_pace_v1(jsonb) set schema profile_data_private;
alter function profile_data_private.native_travel_pace_v1(jsonb) rename to native_original_v1;
revoke all on function profile_data_private.native_original_v1(jsonb) from public,anon,authenticated,service_role;
create function public.native_travel_pace_v1(p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();w profile_data_private.watermarks_v1;p public.user_profiles;e public.user_profiles;r jsonb;a text:=p_input->>'action';begin
 perform identity_private.mobile_session_v2('session');
 if p_input is null or jsonb_typeof(p_input)<>'object' then raise exception 'INVALID_INPUT';end if;
 if a is distinct from 'read' and (jsonb_typeof(p_input->'operationId') is distinct from 'string' or p_input->>'operationId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then raise exception 'INVALID_INPUT';end if;
 begin
  w:=profile_data_private.lock_owner_v1(u);
  select * into p from public.user_profiles where owner_id=u for update nowait;
 exception when lock_not_available then raise exception 'PACE_CONFLICT';
 end;
 if a='read' then
  if p.owner_id is null and w.pace_floor>0 and p_input='{"action":"read"}'::jsonb then p.pace_revision:=w.pace_revision;p.pace_state:='revoked';return memory_private.pace_json(p);end if;
  return profile_data_private.native_original_v1(p_input);
 end if;
 if jsonb_typeof(p_input->'expectedRevision')='number' and p_input->>'expectedRevision' ~ '^(0|[1-9][0-9]{0,15})$' and (p_input->>'expectedRevision')::numeric<w.pace_floor then raise exception 'PACE_CONFLICT';end if;
 -- Legitimate first save/restoration begins at the retained floor, never old bytes.
 if p.owner_id is null then
  insert into profile_data_private.proofs_v1 values(pg_current_xact_id(),u,'native',null,p_input);
  insert into public.user_profiles(owner_id) values(u) returning * into p;
  delete from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id();
 end if;
 e:=p;
 e.travel_pace:=case a when 'save' then p_input->>'travelPace' when 'revoke' then 'balanced' when 'undo' then p.pace_undo->>'travelPace' else p.travel_pace end;
 e.pace_state:=case a when 'save' then 'explicit' when 'pause' then 'paused' when 'revoke' then 'revoked' else p.pace_undo->>'state' end;
 e.pace_notice:=case a when 'save' then p_input->>'noticeVersion' when 'revoke' then null when 'undo' then p.pace_undo->>'noticeVersion' else p.pace_notice end;
 e.pace_revision:=p.pace_revision+1;e.pace_operation:=(p_input->>'operationId')::uuid;e.pace_request:=p_input;
 e.pace_undo:=case when a='save' then jsonb_build_object('travelPace',p.travel_pace,'state',p.pace_state,'noticeVersion',p.pace_notice) else null end;
 insert into profile_data_private.proofs_v1 values(pg_current_xact_id(),u,'native',to_jsonb(e),p_input);
 r:=profile_data_private.native_original_v1(p_input);
 delete from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id();return r;
end$$;
revoke all on function public.native_travel_pace_v1(jsonb) from public,anon,service_role;
grant execute on function public.native_travel_pace_v1(jsonb) to authenticated;

create function profile_data_private.web_save_v1(p_display_name text,p_travel_pace text,p_locale text,p_currency text,p_distance_unit text,p_temperature_unit text,p_default_departure_time time,p_expected_profile_revision bigint)
returns table(owner_id uuid,updated_at timestamptz) language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();w profile_data_private.watermarks_v1;p public.user_profiles;e public.user_profiles;begin
 -- Original Web compatibility guard: no new mobile enrollment prerequisite.
 perform identity_private.guard_mobile_rpc_v2();
 if u is null then raise exception 'FORBIDDEN';end if;
 w:=profile_data_private.lock_owner_v1(u);
 if p_expected_profile_revision is null then if w.profile_floor>0 then raise exception 'PROFILE_WRITE_FENCE';end if;
 elsif p_expected_profile_revision<0 or p_expected_profile_revision>9007199254740990 then raise exception 'INVALID_PROFILE';
 elsif p_expected_profile_revision<>w.profile_revision then raise exception 'PROFILE_CONFLICT';end if;
 if nullif(trim(p_display_name),'') is not null and char_length(trim(p_display_name)) not between 1 and 80 then raise exception 'INVALID_PROFILE';end if;
 if p_travel_pace is null or p_locale is null or p_currency is null or p_distance_unit is null or p_temperature_unit is null or p_default_departure_time is null or p_travel_pace not in('relaxed','balanced','packed') or p_locale not in('zh','en','es','ru','ar') or p_currency not in('CNY','USD','EUR','RUB','SAR') or p_distance_unit not in('kilometre','mile') or p_temperature_unit not in('celsius','fahrenheit') then raise exception 'INVALID_PROFILE';end if;
 select * into p from public.user_profiles where public.user_profiles.owner_id=u for update nowait;
 if p.owner_id is null then
  e:=jsonb_populate_record(null::public.user_profiles,jsonb_build_object('owner_id',u,'profile_revision',w.profile_revision,'pace_revision',w.pace_revision,'pace_state',case when w.pace_floor>0 then 'revoked' else 'unset' end));
 else e:=p;end if;
 e.display_name:=nullif(trim(p_display_name),'');e.travel_pace:=p_travel_pace;e.locale:=p_locale;e.currency:=p_currency;e.distance_unit:=p_distance_unit;e.temperature_unit:=p_temperature_unit;e.default_departure_time:=p_default_departure_time;
 e.profile_saved_fields:='["display_name","travel_pace","locale","currency","distance_unit","temperature_unit","default_departure_time"]';
 if p.owner_id is not null and e.travel_pace is distinct from p.travel_pace then e.pace_revision:=p.pace_revision+1;e.pace_state:='unset';e.pace_notice:=null;e.pace_operation:=null;e.pace_request:=null;e.pace_undo:=null;end if;
 insert into profile_data_private.proofs_v1 values(pg_current_xact_id(),u,'web',to_jsonb(e),null);
 if p.owner_id is null then
  insert into public.user_profiles(owner_id,display_name,travel_pace,locale,currency,distance_unit,temperature_unit,default_departure_time,pace_revision,pace_state,profile_saved_fields)
   values(u,e.display_name,e.travel_pace,e.locale,e.currency,e.distance_unit,e.temperature_unit,e.default_departure_time,e.pace_revision,e.pace_state,e.profile_saved_fields);
  -- First explicit Web form save advances its source revision too.
  select * into e from public.user_profiles where public.user_profiles.owner_id=u;
  update profile_data_private.proofs_v1 set expected_row=to_jsonb(e) where transaction_id=pg_current_xact_id();
  update public.user_profiles set updated_at=clock_timestamp() where public.user_profiles.owner_id=u;
 else
  update public.user_profiles set display_name=e.display_name,travel_pace=e.travel_pace,locale=e.locale,currency=e.currency,distance_unit=e.distance_unit,temperature_unit=e.temperature_unit,default_departure_time=e.default_departure_time,pace_revision=e.pace_revision,pace_state=e.pace_state,pace_notice=e.pace_notice,pace_operation=e.pace_operation,pace_request=e.pace_request,pace_undo=e.pace_undo,profile_saved_fields=e.profile_saved_fields,updated_at=clock_timestamp() where public.user_profiles.owner_id=u;
 end if;
 delete from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id();
 return query select p2.owner_id,p2.updated_at from public.user_profiles p2 where p2.owner_id=u;
end$$;
create or replace function public.save_user_profile(p_display_name text,p_travel_pace text,p_locale text,p_currency text,p_distance_unit text,p_temperature_unit text,p_default_departure_time time)
returns table(owner_id uuid,updated_at timestamptz) language sql security definer set search_path='' as $$select * from profile_data_private.web_save_v1(p_display_name,p_travel_pace,p_locale,p_currency,p_distance_unit,p_temperature_unit,p_default_departure_time,null)$$;
create function public.save_user_profile_v2(p_display_name text,p_travel_pace text,p_locale text,p_currency text,p_distance_unit text,p_temperature_unit text,p_default_departure_time time,p_expected_profile_revision bigint)
returns table(owner_id uuid,updated_at timestamptz) language plpgsql security definer set search_path='' as $$begin
 if p_expected_profile_revision is null then raise exception 'INVALID_PROFILE';end if;
 return query select * from profile_data_private.web_save_v1(p_display_name,p_travel_pace,p_locale,p_currency,p_distance_unit,p_temperature_unit,p_default_departure_time,p_expected_profile_revision);
end$$;
revoke all on function public.save_user_profile_v2(text,text,text,text,text,text,time,bigint) from public,anon,service_role;
grant execute on function public.save_user_profile_v2(text,text,text,text,text,text,time,bigint) to authenticated;

create function profile_data_private.actor_v1(expected_epoch bigint) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare u uuid:=auth.uid();s uuid;e bigint;n timestamptz;begin
 if u is null or auth.role() is distinct from 'authenticated' or auth.jwt()->>'role' is distinct from 'authenticated' or auth.jwt()->>'is_anonymous' is distinct from 'false' or notification_private.uuid(auth.jwt()->'session_id') is not true then raise exception 'UNAUTHENTICATED';end if;
 s:=(auth.jwt()->>'session_id')::uuid;
 -- Original writers lock the mobile account before the Profile source.
 select epoch into e from identity_private.mobile_accounts where owner_id=u and session_id=s for update nowait;
 if not found or e is distinct from expected_epoch then raise exception 'SESSION_REPLACED';end if;
 perform 1 from auth.sessions where id=s and user_id=u for key share nowait;if not found then raise exception 'SESSION_REPLACED';end if;
 perform identity_private.guard_mobile_rpc_v2();
 if not exists(select 1 from identity_private.mobile_attempts where owner_id=u and session_id=s and epoch=e) or not identity_private.mobile_access_v2() then raise exception 'SESSION_REPLACED';end if;
 n:=clock_timestamp();
 if not exists(select 1 from auth.sessions where id=s and user_id=u and created_at between n-interval '5 minutes' and n) then raise exception 'REAUTHENTICATION_REQUIRED';end if;
 perform profile_data_private.lock_owner_v1(u);
 return jsonb_build_object('ownerId',u,'sessionId',s,'mobileEpoch',e);
end$$;
create function profile_data_private.input_v1(v jsonb,a text,recovering boolean default false) returns boolean language plpgsql immutable set search_path='' as $$declare keys_n text[];prior jsonb;begin
 if jsonb_typeof(v) is distinct from 'object' or jsonb_typeof(v->'action') is distinct from 'string' or jsonb_typeof(v->'scope') is distinct from 'string' or v->>'action' is distinct from a or v->>'scope' not in('profile-sensitive-data/1','profile-delete-progress/1') then return false;end if;
 if a='list' then return notification_private.exact(v,array['action','scope','cursor','limit']) and v->'limit'='20'::jsonb and (v->'cursor'='null'::jsonb or notification_private.exact(v->'cursor',array['sourceDigest','afterId']) and notification_private.uuid(v->'cursor'->'afterId') and jsonb_typeof(v->'cursor'->'sourceDigest')='string' and v->'cursor'->>'sourceDigest' ~ '^[a-f0-9]{64}$');end if;
 if notification_private.uuid(v->'requestId') is not true then return false;end if;
 if v->>'scope'='profile-sensitive-data/1' then if notification_private.uuid(v->'profileId') is not true or v->'objectIds' is distinct from '[]'::jsonb then return false;end if;
 else if v->'profileId' is distinct from 'null'::jsonb or conversation_data_private.ids_v1(v->'objectIds',20) is not true or jsonb_array_length(v->'objectIds')<1 or v->'objectIds' ? (v->>'requestId') then return false;end if;end if;
 keys_n:=array['action','scope','requestId','profileId','objectIds'];
 if a='erase' then
  keys_n:=keys_n||array['sourceDigest','previewDigest','confirmed'];
  if v->'confirmed' is distinct from 'true'::jsonb or jsonb_typeof(v->'sourceDigest') is distinct from 'string' or jsonb_typeof(v->'previewDigest') is distinct from 'string' or v->>'sourceDigest' !~ '^[a-f0-9]{64}$' or v->>'previewDigest' !~ '^[a-f0-9]{64}$' or not(v ?& array['sourceDigest','previewDigest']) then return false;end if;
 elsif a='recover' then
  if recovering or jsonb_typeof(v->'mutationBytes') is distinct from 'string' or octet_length(v->>'mutationBytes')>8192 then return false;end if;
  keys_n:=keys_n||array['mutationBytes'];
  begin prior:=(v->>'mutationBytes')::jsonb;exception when others then return false;end;
  if profile_data_private.input_v1(prior,'erase',true) is not true or (v-array['action','mutationBytes']) is distinct from (prior-array['action','sourceDigest','previewDigest','confirmed']) then return false;end if;
 elsif a<>'preview' then return false;end if;
 return notification_private.exact(v,keys_n);
end$$;
create function profile_data_private.profile_v1(p public.user_profiles) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object(
 'displayName',p.display_name,'travelPace',p.travel_pace,'locale',p.locale,'currency',p.currency,'distanceUnit',p.distance_unit,'temperatureUnit',p.temperature_unit,'defaultDepartureTime',p.default_departure_time::text,
 'paceNotice',p.pace_notice,'paceOperation',p.pace_operation,'paceRequest',p.pace_request,'paceUndo',p.pace_undo)$$;
create function profile_data_private.summary_v1(p public.user_profiles,w profile_data_private.watermarks_v1) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object(
 'profileRevision',p.profile_revision,'paceRevision',p.pace_revision,'profileErasureFloor',w.profile_floor,'paceErasureFloor',w.pace_floor,'paceState',p.pace_state,
 'presentFields',p.profile_saved_fields||case when p.pace_notice is not null then '["pace_notice"]'::jsonb else '[]'::jsonb end||case when p.pace_operation is not null then '["pace_operation"]'::jsonb else '[]'::jsonb end||case when p.pace_request is not null then '["pace_request"]'::jsonb else '[]'::jsonb end||case when p.pace_undo is not null then '["pace_undo"]'::jsonb else '[]'::jsonb end,
 'hasPaceRequest',p.pace_request is not null,'hasPaceUndo',p.pace_undo is not null)$$;
create function profile_data_private.operation_row_v1(r profile_data_private.operations_v1) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object(
 'requestId',r.request_id,'ownerId',r.owner_id,'sessionId',r.session_id,'mobileEpoch',r.mobile_epoch,'scope',r.scope,'profileId',r.profile_id,'objectIds',r.object_ids,'sourceDigest',r.source_digest,'previewDigest',r.preview_digest,'capturedAt',r.captured_at,'expiresAt',r.expires_at,'requestDigest',r.request_digest,'state',r.state,'previewErased',r.preview_erased,'summary',r.summary,'copies',r.copies,'conflicts',r.conflicts,'decision',r.decision)$$;
create function profile_data_private.binding_v1(r profile_data_private.operations_v1) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object(
 'schemaVersion','profile-data/1','requestId',r.request_id,'ownerId',r.owner_id,'sessionId',r.session_id,'mobileEpoch',r.mobile_epoch,'scope',r.scope,'profileId',r.profile_id,'objectIds',r.object_ids,'sourceDigest',r.source_digest,'previewDigest',r.preview_digest,'capturedAt',r.captured_at,'expiresAt',r.expires_at,'boundaries',profile_data_private.boundaries_v1(r.scope),'allUserDataCompleted',false)$$;
create function profile_data_private.guard_operation_v1() returns trigger language plpgsql security definer set search_path='' as $$begin
 if TG_OP='DELETE' then if exists(select 1 from auth.users where id=OLD.owner_id) then raise exception 'PROFILE_WRITE_FENCE';end if;return OLD;end if;
 if not exists(select 1 from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id() and owner_id=NEW.owner_id and mode='executor') then raise exception 'PROFILE_WRITE_FENCE';end if;
 if TG_OP='UPDATE' then
  if to_jsonb(NEW)-array['state','request_digest','preview_erased','summary','copies','conflicts','decision'] is distinct from to_jsonb(OLD)-array['state','request_digest','preview_erased','summary','copies','conflicts','decision']
   or OLD.preview_erased and not NEW.preview_erased or OLD.state='erased' and (NEW.state<>'erased' or NEW.decision is distinct from OLD.decision or NEW.request_digest is distinct from OLD.request_digest)
   or NEW.preview_erased and (NEW.summary is not null or NEW.copies is not null or NEW.conflicts is not null) then raise exception 'PROFILE_WRITE_FENCE';end if;
 end if;return NEW;
end$$;
create trigger profile_operation_guard before insert or update or delete on profile_data_private.operations_v1 for each row execute function profile_data_private.guard_operation_v1();

