 ('scoped_edit_private.proofs_v1','context_id=any($3)','proposal_id'),
 ('public.turns','id=any($4)','id'),
 ('turn_private.service_tasks','id in(select task_id from scoped_edit_private.work_v1 where context_id=any($3))','id'),
