 for r in select * from profile_data_private.sources_v1() loop names:=names||r.relation_name;end loop;
 expected:='{"public.turns":{"columns":[["id","uuid",true],["owner_id","uuid",true],["trip_id","uuid",false],["status","text",true],["created_at","timestamp with time zone",true],["thread_id","uuid",false],["updated_at","timestamp with time zone",true]],"constraints":["UNIQUE (id, owner_id)","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (id)","CHECK ((status = ANY (ARRAY[''accepted''::text, ''planning''::text, ''retrieving''::text, ''generating''::text, ''validating''::text, ''completed''::text, ''proposal_ready''::text, ''unavailable''::text, ''failed''::text, ''cancelled''::text])))","FOREIGN KEY (thread_id) REFERENCES public.chat_threads(id) ON DELETE CASCADE","FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE SET NULL"]},"turn_private.work":{"columns":[["turn_id","uuid",true],["owner_id","uuid",true],["session_id","uuid",true],["state","text",true],["attempt","integer",true],["max_attempts","integer",true],["lease_ms","integer",true],["lease_token","uuid",false],["expires_at","timestamp with time zone",false],["created_at","timestamp with time zone",true],["execution_mode","text",true]],"constraints":["CHECK (((attempt >= 0) AND (attempt <= 5)))","CHECK (((state = ''leased''::text) = ((lease_token IS NOT NULL) AND (expires_at IS NOT NULL))))","CHECK (((state = ''leased''::text) OR ((lease_token IS NULL) AND (expires_at IS NULL))))","CHECK ((execution_mode = ANY (ARRAY[''text''::text, ''planning_comparison_v1''::text, ''planning_intake_comparison_v2''::text, ''scoped_trip_edit_v1''::text])))","CHECK (((lease_ms >= 1000) AND (lease_ms <= 300000)))","CHECK (((max_attempts >= 1) AND (max_attempts <= 5)))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (turn_id)","CHECK ((state = ANY (ARRAY[''queued''::text, ''leased''::text, ''completed''::text, ''failed''::text, ''cancelled''::text, ''quarantined''::text])))","FOREIGN KEY (turn_id) REFERENCES public.turns(id) ON DELETE CASCADE"]},"public.user_profiles":{"columns":[["owner_id","uuid",true],["display_name","text",false],["travel_pace","text",true],["locale","text",true],["currency","text",true],["distance_unit","text",true],["temperature_unit","text",true],["default_departure_time","time without time zone",true],["created_at","timestamp with time zone",true],["updated_at","timestamp with time zone",true],["pace_revision","bigint",true],["pace_state","text",true],["pace_notice","text",false],["pace_operation","uuid",false],["pace_request","jsonb",false],["pace_undo","jsonb",false],["profile_revision","bigint",true],["profile_saved_fields","jsonb",true]],"constraints":["CHECK (((pace_state <> ALL (ARRAY[''explicit''::text, ''paused''::text])) OR (pace_notice IS NOT NULL)))","CHECK ((currency = ANY (ARRAY[''CNY''::text, ''USD''::text, ''EUR''::text, ''RUB''::text, ''SAR''::text])))","CHECK (((display_name IS NULL) OR ((char_length(display_name) >= 1) AND (char_length(display_name) <= 80))))","CHECK ((distance_unit = ANY (ARRAY[''kilometre''::text, ''mile''::text])))","CHECK ((locale = ANY (ARRAY[''zh''::text, ''en''::text, ''es''::text, ''ru''::text, ''ar''::text])))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","CHECK (((pace_notice IS NULL) OR (pace_notice = ''local-planning-cross-trip-v1''::text)))","CHECK (((pace_revision >= 0) AND (pace_revision <= ''9007199254740990''::bigint)))","CHECK ((pace_state = ANY (ARRAY[''unset''::text, ''explicit''::text, ''paused''::text, ''revoked''::text])))","PRIMARY KEY (owner_id)","CHECK (((profile_revision >= 0) AND (profile_revision <= ''9007199254740990''::bigint)))","CHECK ((temperature_unit = ANY (ARRAY[''celsius''::text, ''fahrenheit''::text])))","CHECK ((travel_pace = ANY (ARRAY[''relaxed''::text, ''balanced''::text, ''packed''::text])))"]},"public.privacy_requests":{"columns":[["id","uuid",true],["owner_id","uuid",true],["action","text",true],["scope_version","text",true],["status","text",true],["execution_state","text",true],["cre