-- All copies enter the source CAS as complete locked rows, including expired
-- mixed copies. UUID references are exposed only after ordinary owner qualification.
create function profile_data_private.inventory_v1(u uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare p public.user_profiles;w profile_data_private.watermarks_v1;cases uuid[]:=array[]::uuid[];scoped uuid[]:=array[]::uuid[];work_ids uuid[]:=array[]::uuid[];recovery uuid[]:=array[]::uuid[];
 spec record;row_n jsonb;rows_n jsonb:='[]';copies jsonb:=profile_data_private.empty_copies_v1();conflicts text[]:=array[]::text[];n integer:=0;source jsonb;modules jsonb;
begin
 if profile_data_private.schema_v1() is not true then raise exception 'PROFILE_SOURCE_UNAVAILABLE';end if;
 select * into p from public.user_profiles where owner_id=u for update nowait;
 select * into w from profile_data_private.watermarks_v1 where owner_id=u for update nowait;
 if p.owner_id is not null then
  if p.profile_revision<>w.profile_revision or p.pace_revision<>w.pace_revision or jsonb_typeof(p.profile_saved_fields)<>'array'
   or (select coalesce(jsonb_agg(value order by ord),'[]') from jsonb_array_elements('["display_name","travel_pace","locale","currency","distance_unit","temperature_unit","default_departure_time"]') with ordinality f(value,ord) where p.profile_saved_fields ? (value#>>'{}')) is distinct from p.profile_saved_fields
   or (p.pace_request is null)<>(p.pace_operation is null) or p.pace_request is not null and ((p.pace_request->>'operationId')::uuid is distinct from p.pace_operation or (p.pace_request->>'expectedRevision')::bigint+1<>p.pace_revision)
   or p.pace_undo is not null and p.pace_request->>'action' is distinct from 'save' or p.pace_state not in('explicit','paused') and p.pace_notice is not null then raise exception 'PROFILE_SOURCE_UNAVAILABLE';end if;
 end if;
 select coalesce(array_agg(id order by id),'{}') into scoped from (select id from scoped_edit_private.contexts_v1 where owner_id=u order by id limit 10001 for update nowait) s;
 select coalesce(array_agg(id order by id),'{}') into recovery from (select id from recovery_private.contexts_v1 where owner_id=u order by id limit 10001 for update nowait) s;
 select coalesce(array_agg(turn_id order by turn_id),'{}') into work_ids from scoped_edit_private.work_v1 where context_id=any(scoped);
 select coalesce(array_agg(case_id order by case_id),'{}') into cases from (select case_id from service_brief_private.briefs where owner_id=u and state='shared' and sources->'profilePace'='true' union select case_id from service_brief_private.previews where owner_id=u and sources->'profilePace'='true') s;
 if exists(select 1 from unnest(cases) cid where not exists(select 1 from service_cases_private.cases c where c.id=cid and c.owner_id=u))
  or exists(select 1 from scoped_edit_private.contexts_v1 c where c.id=any(scoped) and not exists(select 1 from public.trips t where t.id=c.trip_id and t.owner_id=u))
  or exists(select 1 from recovery_private.contexts_v1 c where c.id=any(recovery) and not exists(select 1 from public.trips t where t.id=c.trip_id and t.owner_id=u))
  or exists(select 1 from scoped_edit_private.work_v1 x where x.context_id=any(scoped) and (x.owner_id<>u or not exists(select 1 from scoped_edit_private.contexts_v1 c where c.id=x.context_id and c.owner_id=x.owner_id and c.trip_id=x.trip_id) or not exists(select 1 from public.model_budget_scopes b where b.id=x.scope_id and b.owner_id=u) or not exists(select 1 from turn_private.service_tasks st where st.id=x.task_id and st.owner_id=u) or not exists(select 1 from turn_private.work t where t.turn_id=x.turn_id and t.owner_id=u))) then raise exception 'PROFILE_SOURCE_UNAVAILABLE';end if;
 if cardinality(scoped)+cardinality(recovery)+cardinality(work_ids)+cardinality(cases)>10000 then raise exception 'PROFILE_SCOPE_TOO_LARGE';end if;
 copies:=jsonb_set(copies,'{scopedEditContexts}',to_jsonb(scoped));copies:=jsonb_set(copies,'{scopedEditWork}',to_jsonb(work_ids));copies:=jsonb_set(copies,'{recoveryContexts}',to_jsonb(recovery));
 for spec in select * from profile_data_private.sources_v1() loop
  for row_n in execute format('select to_jsonb(r) from (select * from %s where %s order by %I limit 10001 for update nowait) r',spec.relation_name,spec.predicate,spec.order_key) using u,cases,scoped,work_ids,recovery loop
   if row_n ? 'owner_id' and row_n->>'owner_id' is distinct from u::text or spec.relation_name='service_brief_private.operations' and row_n->>'actor_id' is distinct from u::text then raise exception 'PROFILE_SOURCE_UNAVAILABLE';end if;
   n:=n+1;if n>10000 then raise exception 'PROFILE_SCOPE_TOO_LARGE';end if;
   rows_n:=rows_n||jsonb_build_array(jsonb_build_object('relation',spec.relation_name,'row',row_n));
   if octet_length(rows_n::text)>1000000 then raise exception 'PROFILE_SCOPE_TOO_LARGE';end if;
   if spec.relation_name='service_brief_private.previews' then
    if service_brief_private.valid_sources(row_n->'sources') is not true then raise exception 'PROFILE_SOURCE_UNAVAILABLE';end if;
    copies:=jsonb_set(copies,'{briefPreviews}',copies->'briefPreviews'||jsonb_build_array(row_n->'id'));
   elsif spec.relation_name='service_brief_private.briefs' and row_n->>'state'='shared' then
    if service_brief_private.valid_sources(row_n->'sources') is not true then raise exception 'PROFILE_SOURCE_UNAVAILABLE';end if;
    copies:=jsonb_set(copies,'{sharedBriefs}',copies->'sharedBriefs'||jsonb_build_array(row_n->'case_id'));
   elsif spec.relation_name='turn_private.work' and row_n->>'state'='leased' then conflicts:=conflicts||array['ACTIVE_PROFILE_USE'];
   elsif spec.relation_name='export_private.core_jobs_v1' then
    modules:=row_n->'modules';
    if modules<>'[]' and export_private.valid_modules_v1(modules,(row_n->'policy_snapshot'->>'max_pages')::integer) is not true then raise exception 'PROFILE_SOURCE_UNAVAILABLE';end if;
    if exists(select 1 from jsonb_array_elements(modules) m where m->>'module'='profile' and ((m->>'pages')::integer>0 or (m->>'rows')::integer>0)) then
     copies:=jsonb_set(copies,'{coreExports}',copies->'coreExports'||jsonb_build_array(row_n->'request_id'));
     conflicts:=conflicts||array['CORE_EXPORT_COPY'];
     if row_n->>'state' in('queued','running') then conflicts:=conflicts||array['SOURCE_UNSUPPORTED'];end if;
    end if;
   elsif spec.relation_name='public.privacy_requests' and row_n->>'action'='delete' and row_n->>'status' in('requested','processing') then conflicts:=conflicts||array['OTHER_DELETE_PENDING'];end if;
  end loop;
 end loop;
 -- Sorting keeps the one public copy inventory finite and canonical.
 for spec in select key from jsonb_each(copies) loop
  copies:=jsonb_set(copies,array[spec.key],(select coalesce(jsonb_agg(value order by value),'[]') from jsonb_array_elements(copies->spec.key)));
 end loop;
 source:=jsonb_build_object('profile',to_jsonb(p),'watermark',to_jsonb(w),'rows',rows_n);
 if octet_length(source::text)>1000000 or (select sum(jsonb_array_length(value)) from jsonb_each(copies))>10000 then raise exception 'PROFILE_SCOPE_TOO_LARGE';end if;
 return jsonb_build_object('sourceDigest',profile_data_private.digest_v1(source::text),'copies',copies,'rows',rows_n,'profile',case when p.owner_id is null then null else profile_data_private.profile_v1(p) end,'summary',case when p.owner_id is null then case when w.profile_floor>0 then jsonb_build_object('profileRevision',w.profile_revision,'paceRevision',w.pace_revision,'profileErasureFloor',w.profile_floor,'paceErasureFloor',w.pace_floor,'paceState','revoked','presentFields','[]'::jsonb,'hasPaceRequest',false,'hasPaceUndo',false) else null end else profile_data_private.summary_v1(p,w) end,
 'conflicts',(select coalesce(jsonb_agg(to_jsonb(k) order by ord),'[]') from unnest(array['SCOPE_TOO_LARGE','ACTIVE_PROFILE_USE','CORE_EXPORT_COPY','OTHER_DELETE_PENDING','SOURCE_UNSUPPORTED']) with ordinality x(k,ord) where k=any(conflicts)));
end$$;
create function profile_data_private.progress_v1(u uuid,ids jsonb default null) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare rows_n jsonb[]:=array[]::jsonb[];items_n jsonb;row_n jsonb;r profile_data_private.operations_v1;n integer:=0;bytes_n bigint:=2;begin
 for r in select * from profile_data_private.operations_v1 where owner_id=u and (ids is null or ids ? request_id::text) order by request_id limit 10001 for update nowait loop
  n:=n+1;if n>10000 then raise exception 'PROFILE_SCOPE_TOO_LARGE';end if;
  row_n:=profile_data_private.operation_row_v1(r);
  bytes_n:=bytes_n+octet_length(row_n::text)+case when n>1 then 2 else 0 end;
  if bytes_n>1000000 then raise exception 'PROFILE_SCOPE_TOO_LARGE';end if;
  rows_n:=array_append(rows_n,row_n);
 end loop;
 if ids is not null and n<>jsonb_array_length(ids) then raise exception 'PROFILE_NOT_FOUND';end if;
 items_n:=to_jsonb(rows_n);
 return jsonb_build_object('items',items_n,'sourceDigest',profile_data_private.digest_v1(items_n::text));
end$$;
-- Exact planned/actual source side effects. Any unexpected mutation rolls back.
create function profile_data_private.verify_effects_v1(inv jsonb) returns void language plpgsql volatile security definer set search_path='' as $$
declare edge jsonb;old_n jsonb;actual_n jsonb;expected_n jsonb;rel text;predicate text;key_n record;count_n integer;cid text;begin
 for edge in select value from jsonb_array_elements(inv->'rows') loop
  rel:=edge->>'relation';old_n:=edge->'row';predicate:='true';
  for key_n in select a.attname from pg_constraint c cross join lateral unnest(c.conkey) with ordinality k(attnum,ord) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum where c.conrelid=rel::regclass and c.contype='p' order by k.ord loop
   predicate:=predicate||format(' and to_jsonb(actual)->%L = $1->%L',key_n.attname,key_n.attname);
  end loop;
  if predicate='true' then raise exception 'PROFILE_EFFECT_MISMATCH';end if;
  execute format('select to_jsonb(actual) from %s actual where %s',rel,predicate) into actual_n using old_n;
  if rel='service_brief_private.previews' then
   if actual_n is not null then raise exception 'PROFILE_EFFECT_MISMATCH';end if;
  elsif rel='service_brief_private.operations' and (old_n->>'erased')::boolean is false and not(old_n->'receipt'->>'action'='delete' and old_n->'receipt'->>'outcome'='applied') then
   expected_n:=old_n||'{"erased":true,"case_id":null,"request_bytes":null,"receipt":null}'::jsonb;
   if actual_n is distinct from expected_n then raise exception 'PROFILE_EFFECT_MISMATCH';end if;
  elsif rel='service_brief_private.briefs' and old_n->>'state'='shared' then
   expected_n:=old_n||jsonb_build_object('revision',(old_n->>'revision')::bigint+1,'state','invalidated','sources',null,'source_digest',null,'selected_keys','[]'::jsonb,'expires_at',null);
   if actual_n-'updated_at' is distinct from expected_n-'updated_at' or (actual_n->>'updated_at')::timestamptz<(old_n->>'updated_at')::timestamptz then raise exception 'PROFILE_EFFECT_MISMATCH';end if;
   cid:=old_n->>'case_id';
   select count(*) into count_n from service_brief_private.audit a where a.case_id::text=cid and not exists(select 1 from jsonb_array_elements(inv->'rows') old_edge where old_edge->>'relation'='service_brief_private.audit' and old_edge->'row'->>'event_id'=a.event_id::text);
   if count_n<>1 or not exists(select 1 from service_brief_private.audit a where a.case_id::text=cid and a.revision=(old_n->>'revision')::bigint+1 and a.action='invalidated' and a.field_keys='[]') then raise exception 'PROFILE_EFFECT_MISMATCH';end if;
  else if actual_n is distinct from old_n then raise exception 'PROFILE_EFFECT_MISMATCH';end if;
  end if;
 end loop;
end$$;
create function profile_data_private.proof_must_clear_v1() returns trigger language plpgsql security definer set search_path='' as $$begin
 if exists(select 1 from profile_data_private.proofs_v1 where transaction_id=NEW.transaction_id) then raise exception 'PROFILE_WRITE_FENCE';end if;return NEW;
end$$;
create constraint trigger profile_proof_must_clear after insert on profile_data_private.proofs_v1 deferrable initially deferred for each row execute function profile_data_private.proof_must_clear_v1();
create function public.privacy_profile_data_v1(p_action text,p_input_bytes text,p_expected_epoch bigint) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v jsonb;original jsonb;bytes_n text:=p_input_bytes;actor jsonb;u uuid;s uuid;epoch_n bigint;scope_n text;id uuid;r profile_data_private.operations_v1;
 inv jsonb;items jsonb;result_n jsonb;source_n text;preview_n text;request_n text;now_n bigint;cursor_id text;has_more boolean;count_n integer;cleared integer:=0;
 p public.user_profiles;e public.user_profiles;w profile_data_private.watermarks_v1;before_profile bigint;before_pace bigint;retained jsonb;decision_n jsonb;cases_n jsonb;
begin
 if p_input_bytes is null or octet_length(p_input_bytes)>(case when p_action='recover' then 16384 else 8192 end) then raise exception 'INVALID_INPUT';end if;
 begin v:=p_input_bytes::jsonb;exception when others then raise exception 'INVALID_INPUT';end;
 if profile_data_private.input_v1(v,p_action) is not true then raise exception 'INVALID_INPUT';end if;
 if p_action='erase' and octet_length(jsonb_build_object('action','recover','scope',v->'scope','requestId',v->'requestId','profileId',v->'profileId','objectIds',v->'objectIds','mutationBytes',p_input_bytes)::text)>16384 then raise exception 'INVALID_INPUT';end if;
 actor:=profile_data_private.actor_v1(p_expected_epoch);u:=(actor->>'ownerId')::uuid;s:=(actor->>'sessionId')::uuid;epoch_n:=(actor->>'mobileEpoch')::bigint;
 scope_n:=v->>'scope';
 if scope_n='profile-sensitive-data/1' and p_action<>'list' and v->>'profileId' is distinct from u::text then raise exception 'FORBIDDEN';end if;
 if p_action='recover' then bytes_n:=v->>'mutationBytes';v:=bytes_n::jsonb;end if;
 request_n:=profile_data_private.digest_v1(bytes_n);
 if p_action='list' then
  if scope_n='profile-sensitive-data/1' then
   inv:=profile_data_private.inventory_v1(u);source_n:=inv->>'sourceDigest';
   items:=case when inv->'summary'='null' then '[]'::jsonb else jsonb_build_array(jsonb_build_object('profileId',u,'summary',inv->'summary')) end;
  else inv:=profile_data_private.progress_v1(u);source_n:=inv->>'sourceDigest';items:=inv->'items';end if;
  cursor_id:=v->'cursor'->>'afterId';
  if cursor_id is not null then
   if v->'cursor'->>'sourceDigest' is distinct from source_n or not exists(select 1 from jsonb_array_elements(items) x where case when scope_n='profile-sensitive-data/1' then x->>'profileId' else x->>'requestId' end=cursor_id) then raise exception 'PROFILE_CONFLICT';end if;
  end if;
  select count(*)>20 into has_more from jsonb_array_elements(items) x where cursor_id is null or case when scope_n='profile-sensitive-data/1' then x->>'profileId' else x->>'requestId' end>cursor_id;
  select coalesce(jsonb_agg(x order by sort_id),'[]') into items from (select x,case when scope_n='profile-sensitive-data/1' then x->>'profileId' else x->>'requestId' end sort_id from jsonb_array_elements(items) x where cursor_id is null or case when scope_n='profile-sensitive-data/1' then x->>'profileId' else x->>'requestId' end>cursor_id order by sort_id limit 20) page;
  now_n:=profile_data_private.now_v1();
  result_n:=jsonb_build_object('schemaVersion','profile-data/1','kind','list','scope',scope_n,'sourceDigest',source_n,'capturedAt',now_n,'expiresAt',now_n+30000,'items',items,'hasMore',has_more,'nextCursor',case when has_more then jsonb_build_object('sourceDigest',source_n,'afterId',items->19->>'requestId') else null end,'allUserDataCompleted',false)||actor;
 else
  id:=(v->>'requestId')::uuid;
  -- Request rows are locked after the full source graph for mutation paths.
  if p_action='recover' then
   select * into r from profile_data_private.operations_v1 where request_id=id for update nowait;
   if not found then result_n:=jsonb_build_object('schemaVersion','profile-data/1','kind','unknown','scope',scope_n,'requestId',id,'profileId',v->'profileId','objectIds',v->'objectIds','requestDigest',request_n,'allUserDataCompleted',false)||actor;
   else
    if r.owner_id<>u or r.session_id<>s or r.mobile_epoch<>epoch_n or r.scope<>scope_n or to_jsonb(r.profile_id) is distinct from nullif(v->'profileId','null'::jsonb) or r.object_ids is distinct from v->'objectIds' then raise exception 'PROFILE_REQUEST_REUSE';end if;
    if r.state='erased' then
     if r.request_digest is distinct from request_n or r.source_digest is distinct from v->>'sourceDigest' or r.preview_digest is distinct from v->>'previewDigest' then raise exception 'PROFILE_REQUEST_REUSE';end if;
     result_n:=profile_data_private.binding_v1(r)||jsonb_build_object('kind','receipt','state','erased','decision',r.decision);
    else result_n:=jsonb_build_object('schemaVersion','profile-data/1','kind','unknown','scope',scope_n,'requestId',id,'profileId',v->'profileId','objectIds',v->'objectIds','requestDigest',request_n,'allUserDataCompleted',false)||actor;end if;
   end if;
  else
   if scope_n='profile-sensitive-data/1' then inv:=profile_data_private.inventory_v1(u);if inv->'profile'='null' then raise exception 'PROFILE_NOT_FOUND';end if;
   else inv:=profile_data_private.progress_v1(u,v->'objectIds');inv:=inv||jsonb_build_object('profile',null,'summary',null,'copies',profile_data_private.empty_copies_v1(),'conflicts','[]'::jsonb);end if;
   source_n:=inv->>'sourceDigest';
   select * into r from profile_data_private.operations_v1 where request_id=id for update nowait;
   if found and (r.owner_id<>u or r.session_id<>s or r.mobile_epoch<>epoch_n or r.scope<>scope_n or to_jsonb(r.profile_id) is distinct from nullif(v->'profileId','null'::jsonb) or r.object_ids is distinct from v->'objectIds') then raise exception 'PROFILE_REQUEST_REUSE';end if;
   if p_action='preview' then
    if r.request_id is null then
     if (select count(*) from profile_data_private.operations_v1 where owner_id=u)>=10000 then raise exception 'PROFILE_SCOPE_TOO_LARGE';end if;
     now_n:=profile_data_private.now_v1();
     preview_n:=profile_data_private.digest_v1(jsonb_build_object('actor',actor,'selection',v-array['action'],'sourceDigest',source_n,'capturedAt',now_n,'expiresAt',now_n+30000,'summary',inv->'summary','copies',inv->'copies','conflicts',inv->'conflicts')::text);
     insert into profile_data_private.proofs_v1 values(pg_current_xact_id(),u,'executor',null,null);
     insert into profile_data_private.operations_v1(request_id,owner_id,session_id,mobile_epoch,scope,profile_id,object_ids,source_digest,preview_digest,captured_at,expires_at,state,summary,copies,conflicts)
      values(id,u,s,epoch_n,scope_n,(v->>'profileId')::uuid,v->'objectIds',source_n,preview_n,now_n,now_n+30000,'previewed',nullif(inv->'summary','null'::jsonb),inv->'copies',inv->'conflicts') returning * into r;
     delete from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id();
    else
     if r.state<>'previewed' or r.preview_erased then raise exception 'PROFILE_REQUEST_REUSE';end if;
     if source_n is distinct from r.source_digest then raise exception 'PROFILE_CONFLICT';end if;
    end if;
    perform profile_data_private.deadline_v1(r.captured_at,r.expires_at);
    result_n:=profile_data_private.binding_v1(r)||jsonb_build_object('kind','preview','profile',inv->'profile','summary',inv->'summary','copies',r.copies,'conflicts',r.conflicts,'eligible',r.conflicts='[]'::jsonb,'progressCount',case when scope_n='profile-sensitive-data/1' then 0 else jsonb_array_length(r.object_ids) end);
   else
    if r.request_id is null then raise exception 'PROFILE_NOT_FOUND';end if;
    if r.state='erased' then
     if r.request_digest is distinct from request_n then raise exception 'PROFILE_REQUEST_REUSE';end if;
     result_n:=profile_data_private.binding_v1(r)||jsonb_build_object('kind','receipt','state','erased','decision',r.decision);
    else
     perform profile_data_private.deadline_v1(r.captured_at,r.expires_at);
     if r.preview_erased or r.source_digest is distinct from v->>'sourceDigest' or r.preview_digest is distinct from v->>'previewDigest' or source_n is distinct from r.source_digest then raise exception 'PROFILE_CONFLICT';end if;
     if r.conflicts<>'[]'::jsonb or inv->'conflicts'<>'[]'::jsonb then raise exception 'PROFILE_CONFLICT';end if;
     retained:=r.copies;cases_n:='[]';
     if scope_n='profile-sensitive-data/1' then
      select * into p from public.user_profiles where owner_id=u for update nowait;
      select * into w from profile_data_private.watermarks_v1 where owner_id=u for update nowait;
      before_profile:=p.profile_revision;before_pace:=p.pace_revision;e:=p;
      e.display_name:=null;e.travel_pace:='balanced';e.locale:='zh';e.currency:='CNY';e.distance_unit:='kilometre';e.temperature_unit:='celsius';e.default_departure_time:='09:00:00';
      e.pace_state:='revoked';e.pace_notice:=null;e.pace_operation:=null;e.pace_request:=null;e.pace_undo:=null;e.pace_revision:=p.pace_revision+1;e.profile_revision:=p.profile_revision+1;e.profile_saved_fields:='[]';
      insert into profile_data_private.proofs_v1 values(pg_current_xact_id(),u,'erase',to_jsonb(e),null);
      update public.user_profiles set display_name=null,travel_pace='balanced',locale='zh',currency='CNY',distance_unit='kilometre',temperature_unit='celsius',default_departure_time='09:00:00',pace_state='revoked',pace_notice=null,pace_operation=null,pace_request=null,pace_undo=null,pace_revision=e.pace_revision,profile_saved_fields='[]',updated_at=clock_timestamp() where owner_id=u returning * into e;
      delete from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id();
      -- Original source trigger owns these effects; compare every planned edge.
      cases_n:=r.copies->'sharedBriefs';
      if exists(select 1 from service_brief_private.briefs where r.copies->'sharedBriefs' ? case_id::text and (state<>'invalidated' or sources is not null or selected_keys<>'[]')) or exists(select 1 from service_brief_private.previews bp where r.copies->'briefPreviews' ? bp.id::text)
       or e.profile_revision<>before_profile+1 or e.pace_revision<>before_pace+1 or e.profile_saved_fields<>'[]' or e.created_at<>p.created_at then raise exception 'PROFILE_EFFECT_MISMATCH';end if;
      select * into w from profile_data_private.watermarks_v1 where owner_id=u;
      if w.profile_floor<>e.profile_revision or w.pace_floor<>e.pace_revision then raise exception 'PROFILE_EFFECT_MISMATCH';end if;
      perform profile_data_private.verify_effects_v1(inv);
      retained:=jsonb_set(jsonb_set(retained,'{briefPreviews}','[]'),'{sharedBriefs}','[]');
     else
      insert into profile_data_private.proofs_v1 values(pg_current_xact_id(),u,'executor',null,null);
      select count(*) into cleared from profile_data_private.operations_v1 where owner_id=u and r.object_ids ? request_id::text and not preview_erased;
      update profile_data_private.operations_v1 set preview_erased=true,summary=null,copies=null,conflicts=null where owner_id=u and r.object_ids ? request_id::text;
      get diagnostics count_n=row_count;if count_n<>jsonb_array_length(r.object_ids) then raise exception 'PROFILE_EFFECT_MISMATCH';end if;
      delete from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id();
     end if;
     now_n:=profile_data_private.deadline_v1(r.captured_at,r.expires_at);
     decision_n:=jsonb_build_object('requestDigest',request_n,'decidedAt',now_n,'beforeProfileRevision',before_profile,'afterProfileRevision',case when before_profile is not null then before_profile+1 else null end,'beforePaceRevision',before_pace,'afterPaceRevision',case when before_pace is not null then before_pace+1 else null end,
      'erasedFields',case when scope_n='profile-sensitive-data/1' then profile_data_private.boundaries_v1(scope_n)->'eraseFields' else '[]'::jsonb end,'briefCasesInvalidated',cases_n,'retainedCopies',retained,'clearedPreviews',cleared,'retainedFences',case when scope_n='profile-sensitive-data/1' then 1 else jsonb_array_length(r.object_ids) end,
      'sourceProfile',case when scope_n='profile-sensitive-data/1' then 'cleared' else 'not_modified' end,'paceConsent',case when scope_n='profile-sensitive-data/1' then 'revoked' else 'not_modified' end,'account','not_modified','sourceTrip','not_modified','explicitMemory','not_modified','financialProvider','not_modified','externalCopies','not_erased');
     insert into profile_data_private.proofs_v1 values(pg_current_xact_id(),u,'executor',null,null);
     update profile_data_private.operations_v1 set state='erased',request_digest=request_n,decision=decision_n,preview_erased=true,summary=null,copies=null,conflicts=null where request_id=id returning * into r;
     delete from profile_data_private.proofs_v1 where transaction_id=pg_current_xact_id();
     result_n:=profile_data_private.binding_v1(r)||jsonb_build_object('kind','receipt','state','erased','decision',decision_n);
    end if;
   end if;
  end if;
 end if;
 -- Absolute time and actual authority after all effects: exceptions roll back
 -- original Brief effects, source, floors and immutable receipt together.
 if profile_data_private.actor_v1(p_expected_epoch) is distinct from actor then raise exception 'SESSION_REPLACED';end if;
 if p_action<>'recover' and result_n->>'kind' in('preview','list') then perform profile_data_private.deadline_v1((result_n->>'capturedAt')::bigint,(result_n->>'expiresAt')::bigint);end if;
 if p_action='erase' and r.state='erased' and decision_n is not null then perform profile_data_private.deadline_v1(r.captured_at,r.expires_at);end if;
 if octet_length(result_n::text)>1000000 then raise exception 'PROFILE_SCOPE_TOO_LARGE';end if;
 return result_n;
exception when lock_not_available then raise exception 'PROFILE_CONFLICT';end$$;
revoke all on function public.privacy_profile_data_v1(text,text,bigint) from public,anon,authenticated,service_role;
-- Every private helper is default denied, including SECURITY DEFINER helpers.
revoke all on all functions in schema profile_data_private from public,anon,authenticated,service_role;

-- Exact append compatibility approved by Main after whole source/delta/negative review.
-- Fixed Result baseline 92e338e19450061f4e048c92177256461825a596.
-- New Profile JSON has no Result authority. Enforce this on every insert/update,
-- with the original immutable typed-reference parser; no global per-user scan.
create function profile_data_private.no_result_references_v1(v jsonb) returns boolean language plpgsql immutable set search_path='' as $$begin
 return not exists(select 1 from result_data_private.json_references_v1(v));
exception when others then return false;end$$;
alter table profile_data_private.operations_v1 add constraint profile_operation_no_result_references
 check(profile_data_private.no_result_references_v1(jsonb_build_array(summary,copies,conflicts,decision)));
alter table profile_data_private.proofs_v1 add constraint profile_proof_no_result_references
 check(profile_data_private.no_result_references_v1(jsonb_build_array(expected_row,input)));
revoke all on function profile_data_private.no_result_references_v1(jsonb) from public,anon,authenticated,service_role;

-- Exact complete application-catalog hash after the reviewed Profile delta.
create or replace function result_data_private.schema_supported_v1() returns boolean language sql stable security definer set search_path='' as $$
 select profile_data_private.schema_v1() and result_data_private.infrastructure_supported_v1() and result_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(pg_get_constraintdef(k.oid) order by k.conname) from pg_constraint k where k.conrelid=c.oid)) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','extensions','auth','result_data_private','storage','realtime','_realtime','vault','supabase_functions','supabase_migrations'))::text)='1b026808c513d02dbe168a5fd2698f624283075ba2ae8b8e265e7f4ce4381324'
$$;
